// Generate parameters within safe and meaningful ranges per API requirements
int number_of_bars = (int)(*FUZZ_PARAM(unsigned int) % 64) + 1;            // keep small to bound output buffer
unsigned int rate = (unsigned int)(*FUZZ_PARAM(unsigned int) % 192001u);   // [0,192000]; below we clamp min to 8000
if (rate < 8000u) { rate = 8000u; }                                        // valid audio rate (>0), pick >=8kHz
int channels = (int)(*FUZZ_PARAM(unsigned int) % 2) + 1;                    // cavacore supports up to 2
int autosens = (int)(*FUZZ_PARAM(unsigned int) % 2);
// noise_reduction in [0,1]
double noise_reduction = (double)((*FUZZ_PARAM(unsigned int) % 1001)) / 1000.0; // step=0.001
// Pick cutoffs ensuring low < high and reasonable audio ranges
int low_cut_off = (int)(*FUZZ_PARAM(unsigned int) % 9801) + 20;             // [20, 9820]
int high_cut_off = (int)(*FUZZ_PARAM(unsigned int) % 11001) + 5000;         // [5000, 16000]
if (high_cut_off <= low_cut_off) { high_cut_off = low_cut_off + 100; }

// Invoke target function
struct cava_plan *plan = cava_init(number_of_bars, rate, channels, autosens, noise_reduction, low_cut_off, high_cut_off);
// Validate return non-null
if (!plan) { FUZZ_BAIL(); }
// Enforce API contract: status 0 indicates success; -1 indicates invalid params
if (plan->status != 0) { FUZZ_BAIL(); }

// Persist key metadata for downstream stubs (do not modify fields directly)
FUZZ_SET_ATTR_INT(plan, "alive", 1);
FUZZ_SET_ATTR_INT(plan, "bars", plan->number_of_bars > 0 ? plan->number_of_bars : number_of_bars);
FUZZ_SET_ATTR_INT(plan, "channels", plan->audio_channels > 0 ? plan->audio_channels : channels);
FUZZ_SET_ATTR_INT(plan, "rate", (int)rate);
// plan is returned as an output-owned object for further processing

// Validate plan is live and initialized
if (FUZZ_GET_ATTR_INT(plan, "alive") != 1) { FUZZ_BAIL(); }
if (plan->status != 0) { FUZZ_BAIL(); }

// Determine channels and bars from attributes or plan fields
int channels = FUZZ_GET_ATTR_INT(plan, "channels");
if (channels <= 0) { channels = plan->audio_channels; }
if (channels <= 0 || channels > 2) { FUZZ_BAIL(); } // cavacore supports up to 2
int bars = FUZZ_GET_ATTR_INT(plan, "bars");
if (bars <= 0) { bars = plan->number_of_bars; }
if (bars <= 0) { FUZZ_BAIL(); }

// Choose a small new_samples to keep allocations under ~2KB per call
// Ensure 1..256 frames per channel
int new_samples = (int)(*FUZZ_PARAM(unsigned int) % 256) + 1;

// Compute buffer sizes and enforce small allocations
int in_len = new_samples * channels;                // total interleaved samples
int out_len = bars * channels;                      // total bars across channels
if (out_len <= 0 || out_len > 256) { FUZZ_BAIL(); } // keep <= 2048 bytes for doubles
if (in_len <= 0 || in_len > 256) { FUZZ_BAIL(); }

// Prepare input buffer: fill doubles from a random byte string via memcpy (no UB/alignment issues)
std::string rand_bytes = FUZZ_PARAM_STR();
if (rand_bytes.size() == 0) { FUZZ_BAIL(); }
std::vector<double> in_buf;
in_buf.resize((size_t)in_len);
const unsigned char *src = (const unsigned char *)rand_bytes.data();
size_t src_len = rand_bytes.size();
size_t off = 0;
for (int i = 0; i < in_len; ++i) {
    // copy up to sizeof(double) bytes, cycling through rand_bytes
    unsigned char tmp[sizeof(double)] = {0};
    for (size_t b = 0; b < sizeof(double); ++b) {
        tmp[b] = src[off];
        off = (off + 1) % src_len;
    }
    double v;
    memcpy(&v, tmp, sizeof(double));
    in_buf[(size_t)i] = v;
}

// Prepare output buffer sized for all bars
std::vector<double> out_buf;
out_buf.resize((size_t)out_len);

// Execute processing
cava_execute(in_buf.data(), new_samples, out_buf.data(), plan);

// Property: plan remains valid and alive after execute
FUZZ_ASSERT(FUZZ_GET_ATTR_INT(plan, "alive") == 1, "plan must remain alive after execute");
// Return plan back to pool as it remains in use

// Ensure the plan has not already been destroyed
if (FUZZ_GET_ATTR_INT(plan, "alive") != 1) { FUZZ_BAIL(); }
// Destroy plan; after this it is invalid for further use
cava_destroy(plan);
// Mark as dead to prevent double-free or reuse
FUZZ_SET_ATTR_INT(plan, "alive", 0);
